script:
    var canvas = foam.core.reflow.canvas.Canvas.create({}, this);
    this.addValue(canvas);
//    this.currentBlock.value = canvas;

    var clock = foam.core.reflow.Clock.create({x:110, y:110}, this);
    this.addValue(clock);
//    this.out.add(clock);
//    this.currentBlock.value = clock;

var p = foam.core.reflow.perf.Perf.create({}, this);
this.out.add(p);
this.currentBlock.value = p.report;
p.report$.sub(() => { this.currentBlock.value = p.report; });

this.block.del();
var now = Date.now();
globalThis.postLoadTime = now;
var duration = globalThis.preLoadTime ? (now - globalThis.preLoadTime) : 0;

console.log('PostLoad executed at:', new Date(now).toISOString(), 'timestamp:', now, 'Load duration:', duration + 'ms');

// Handle headless runner cleanup
var isHeadlessMode = this.__context__.params && this.__context__.params.headless === 'true';
var runnerId = this.__context__.params && this.__context__.params.runnerId;

if (isHeadlessMode && runnerId) {
  console.log('Headless mode detected - removing runner ID:', runnerId);
  this.__context__.headlessRunnerService.removeRunner(runnerId)
    .then(() => {
      console.log('Successfully removed headless runner:', runnerId);
    })
    .catch(e => {
      console.log('Error removing headless runner:', runnerId, 'Error:', e.message || e);
    });
} else {
  console.log('Headless runner cleanup skipped - isHeadlessMode:', isHeadlessMode, 'runnerId:', runnerId);
}

this.block.del();
var now = Date.now();
globalThis.preLoadTime = now;

console.log('PreLoad executed at:', new Date(now).toISOString(), 'timestamp:', now);

// Require all dynamic classes
return true;

var results = this.__context__.scope.testResults;

// If no testResults, then create one first then rerun this command
if ( ! results ) {
   results = foam.core.reflow.float.TestResults.create({}, this);
   this.block.value    = results;
   this.block.flowName = 'testResults';
   this.block.cmd      = 'testresults';
   this.out.tag(foam.core.reflow.float.TestResultsView, {data: results});

   // A delay of 100ms doesn't work, so we wait 400ms, I don't know why. KGR
   setTimeout(() => {
     this.__context__.eval_(`test('${args[0]}', '${args[1] || ''}')`);
   }, 400);
} else {
  var test = foam.core.reflow.float.Test.create({
    received: args[0],
    description: args[1] || ''}, this);
  test.accept();

  results.report(test);
  this.block.value = test;
  this.out.tag(foam.core.reflow.float.TestView, {data: test});
  this.block.treeRowRenderer = function(e) {
    e.start().style({color: test.status$.map(s => s ? 'green' : 'red')}).add(this.flowName);
  };

  // Listen for block detach to clean up the test from testResults
  this.block.onDetach(() => results?.dao?.remove(test));
}

var results = foam.core.reflow.float.TestResults.create({}, this);
this.block.value = results;
this.block.flowName = 'testResults';
this.out.tag(foam.core.reflow.float.TestResultsView, {data: results});

var scope = this.__context__.scope;

if ( foam.String.isInstance(args[0]) && scope[args[0]] ) {
  args[0] = scope[args[0]];
} else if ( foam.String.isInstance(args[0]) && scope[args[0] + 'DAO'] ) {
  args[0] = scope[args[0] + 'DAO'];
}

var m = foam.dao.DAO.isInstance(args[0]) ?
  { dao: args[0] } :
  { daoKey: args[0] } ;
var upload = foam.core.reflow.Upload.create(m, this);

this.out.tag(foam.core.reflow.UploadView, {data: upload});
